  this.adK = "\u0412\u0443\u0437\u043e\u043b \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0435\u043d\u043e";
  this.adh = "\u041b\u0430\u043d\u0446\u044e\u0436\u043e\u043a \u043d\u0430\u0437\u0438\u0432\u0430\u0454 \u043a\u043b\u044e\u0447 \u0456\u043d\u0448\u043e\u0433\u043e \u0432\u0443\u0437\u043b\u0430.";
  this.afp = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u043d\u0430 \u0432\u0443\u0437\u043b\u0456 \u043d\u0435 \u0437\u0431\u0456\u0433\u0430\u0454\u0442\u044c\u0441\u044f \u0437 \u0442\u0438\u043c, \u0449\u043e \u0434\u0430\u044e\u0442\u044c \u0439\u043e\u0433\u043e \u0436 \u0437\u0430\u043f\u0438\u0441\u0438.";
  this.af0 = "\u0412\u0443\u0437\u043e\u043b \u043d\u0435 \u0434\u0430\u0432 \u0434\u043e\u043a\u0430\u0437\u0443 \u0434\u043b\u044f \u0446\u044c\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443.";
  this.aeb = "\u0417\u0432\u0435\u0434\u0435\u043d\u043d\u044f \u0432\u0443\u0437\u043b\u0430 \u043d\u0435 \u043f\u0456\u0434\u043f\u0438\u0441\u0430\u043d\u0435 \u0439\u043e\u0433\u043e \u043a\u043b\u044e\u0447\u0435\u043c.";
  this.afn = "\u0412\u0430\u0448 \u043b\u0430\u043d\u0446\u044e\u0436\u043e\u043a \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442\u044c \u0434\u043e \u043f\u0456\u0434\u043f\u0438\u0441\u0430\u043d\u043e\u0433\u043e \u0437\u0432\u0435\u0434\u0435\u043d\u043d\u044f \u0432\u0443\u0437\u043b\u0430.";
  this.ae1 = "\u0426\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043f\u043e\u0440\u0430\u0445\u0443\u0432\u0430\u0432 \u0443\u0441\u0435 \u0441\u0430\u043c; \u0443 \u0432\u0443\u0437\u043b\u0430 \u0431\u0443\u043b\u043e \u0437\u0430\u043f\u0438\u0442\u0430\u043d\u043e \u043b\u0438\u0448\u0435 \u0437\u0430\u043f\u0438\u0441\u0438.";
  this.aeL = "\u0423\u0447\u0430\u0441\u043d\u0438\u043a\u0438";
  this.agn = "\u0421\u0443\u043c\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0456\u0432";
  this.ago = "\u0421\u0443\u043c\u0430 \u0432\u0441\u0456\u0445 \u0431\u0430\u043b\u0430\u043d\u0441\u0456\u0432 \u0437\u0430\u0432\u0436\u0434\u0438 \u0434\u043e\u0440\u0456\u0432\u043d\u044e\u0454 \u043d\u0443\u043b\u044e: \u043e\u0434\u0438\u043d\u0438\u0446\u044f \u043d\u0430\u0440\u043e\u0434\u0436\u0443\u0454\u0442\u044c\u0441\u044f, \u043a\u043e\u043b\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u043a\u0443\u043f\u0443\u0454, \u0456 \u0437\u043d\u0438\u043a\u0430\u0454, \u043a\u043e\u043b\u0438 \u0432\u0456\u043d \u043f\u0440\u043e\u0434\u0430\u0454.";
  this.aeK = "\u0423\u0447\u0430\u0441\u043d\u0438\u043a";
