  this.aej = "\u0406\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440";
  this.agC = "\u041e\u0431\u0440\u0430\u0442\u0438";
  this.afE = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0430\u0431\u043e \u0434\u043e\u0434\u0430\u0442\u0438 \u0449\u0435";
  this.aev = "\u0426\u0435 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0446\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043c\u043e\u0436\u0435 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u0437\u0430 \u043e\u0434\u0438\u043d \u0440\u0430\u0437.";
  this.aew = "\u0426\u0435 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0446\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043c\u043e\u0436\u0435 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u0437\u0430 \u0442\u0438\u0436\u0434\u0435\u043d\u044c.";
  this.agB = "\u0426\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043d\u0435 \u0442\u0440\u0438\u043c\u0430\u0454 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0430\u0431\u043e \u043d\u0435 \u043c\u0430\u0454 \u043d\u0430 \u0446\u0435 \u043f\u0440\u0430\u0432\u0430.";
