  this.aeu = "\u041e\u0434\u0438\u043d \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043c\u0430\u0454 \u0437\u0430\u043b\u0438\u0448\u0438\u0442\u0438\u0441\u044f.";
