  this.adH = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0437\u0430 \u0446\u0435\u0439 \u0447\u0430\u0441 \u0437\u043c\u0456\u043d\u0438\u0432\u0441\u044f. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437.";
