  this.afm = "\u0426\u0435 \u043d\u0435 \u0442\u043e\u043a\u0435\u043d \u0437\u0430\u0441\u043d\u043e\u0432\u043d\u0438\u043a\u0430.";
  this.agb = "\u0426\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u0443 \u0432\u0436\u0435 \u0437\u0430\u0441\u043d\u043e\u0432\u0430\u043d\u043e.";
  this.afw = "\u0412\u0443\u0437\u043e\u043b \u043d\u0435 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0454. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0437\u2019\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0456 \u0441\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437.";
  this.ae4 = "\u0417\u043d\u0430\u0439\u0434\u0456\u0442\u044c \u0441\u0432\u043e\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u0443";
  this.ae5 = "\u041a\u043e\u0436\u043d\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u0430\u0454 \u0432\u043b\u0430\u0441\u043d\u0438\u0439 \u0432\u0443\u0437\u043e\u043b, \u0441\u0432\u043e\u0457\u0445 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u0456 \u043f\u0440\u0430\u0432\u0438\u043b\u0430. \u041e\u0431\u0435\u0440\u0456\u0442\u044c \u0441\u0432\u043e\u044e, \u0432\u0432\u0435\u0434\u0456\u0442\u044c \u0430\u0434\u0440\u0435\u0441\u0443, \u044f\u043a\u0443 \u0432\u043e\u043d\u0430 \u0432\u0430\u043c \u0434\u0430\u043b\u0430, \u0430\u0431\u043e \u0441\u0442\u0432\u043e\u0440\u0456\u0442\u044c \u043d\u043e\u0432\u0443.";
