  this.adV = "\u0421\u0442\u0432\u043e\u0440\u0438\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0443";
  this.adW = "\u0412\u0438 \u0441\u0442\u0430\u0454\u0442\u0435 \u0457\u0457 \u0437\u0430\u0441\u043d\u043e\u0432\u043d\u0438\u043a\u043e\u043c: \u043a\u043b\u044e\u0447 \u0432\u0430\u0448\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e \u0432\u0456\u0434\u043a\u0440\u0438\u0432\u0430\u0454 \u0432\u043b\u0430\u0441\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0433\u0440\u043e\u043c\u0430\u0434\u0438, \u0456 \u0437 \u043d\u044c\u043e\u0433\u043e \u0432\u0438 \u043f\u0440\u0438\u0439\u043c\u0430\u0454\u0442\u0435 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u0442\u0430 \u0437\u0430\u0434\u0430\u0454\u0442\u0435 \u0457\u043c \u043b\u0456\u043c\u0456\u0442\u0438. \u0411\u0456\u043b\u044c\u0448\u0435 \u043d\u0435\u044e \u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u043a\u0435\u0440\u0443\u0454.";
