  this.adb = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.ag1 = "\u0412\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.add = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.ag2 = "\u0412\u0456\u0434\u0445\u0438\u043b\u0435\u043d\u043e";
  this.afa = "\u041d\u0435 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.afS = "\u0426\u0435 \u043c\u0456\u0441\u0446\u0435 \u0437\u0430\u0439\u043d\u044f\u0442\u0435: \u043e\u0431\u0435\u0440\u0456\u0442\u044c \u0456\u043d\u0448\u0435.";
  this.afQ = "\u0423 \u043c\u0456\u0441\u0446\u0456 \u2014 \u0432\u0456\u0434 3 \u0434\u043e 40 \u043c\u0430\u043b\u0438\u0445 \u043b\u0430\u0442\u0438\u043d\u0441\u044c\u043a\u0438\u0445 \u043b\u0456\u0442\u0435\u0440, \u0446\u0438\u0444\u0440 \u0430\u0431\u043e \u0434\u0435\u0444\u0456\u0441\u0456\u0432; \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043b\u0456\u0442\u0435\u0440\u0438.";
  this.aei = "\u0421\u044c\u043e\u0433\u043e\u0434\u043d\u0456 \u0437\u0432\u0456\u0434\u0441\u0438 \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0441\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0438.";
  this.aeh = "\u0422\u0443\u0442 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0441\u0442\u0432\u043e\u0440\u044e\u0454 \u043d\u0435 \u043a\u043e\u0436\u0435\u043d: \u0437\u0432\u0435\u0440\u043d\u0456\u0442\u044c\u0441\u044f \u0434\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0446\u044c\u043e\u0433\u043e \u0441\u0430\u0439\u0442\u0443.";
  this.adg = "\u0406\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430";
  this.agA = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f";
  this.afL = "\u0414\u043e \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.agK = "\u0414\u043e \u044f\u043a\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.af4 = "\u0423 \u0442\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0456\u043a\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u0438.";
  this.agy = "\u041b\u0456\u043d\u0456\u0457 \u0434\u043e\u0432\u0456\u0440\u0438";
  this.aeE = "\u041b\u0456\u043d\u0456\u044f \u0434\u043e\u0432\u0456\u0440\u0438 \u043a\u0430\u0436\u0435, \u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0456\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0430 \u043d\u0430\u0448\u0456\u0439. \u0422\u043e\u0434\u0456 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043c\u043e\u0436\u0443\u0442\u044c \u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u043d\u0430\u0448\u0438\u043c, \u0430 \u043d\u0430\u0448\u0456 \u2014 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430\u043c, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0412\u041e\u041d\u0410 \u0434\u043e\u0432\u0456\u0440\u044f\u0454 \u043d\u0430\u043c. \u041f\u043b\u044e\u0441 \u043d\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0456: \u0432\u0438\u043d\u043d\u0456 \u043c\u0438; \u043c\u0456\u043d\u0443\u0441: \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c.";
  this.agu = "\u041c\u043e\u0436\u0443\u0442\u044c \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c";
  this.aeY = "\u043b\u0456\u043d\u0456\u0439 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0435\u043c\u0430\u0454";
  this.afD = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u043b\u0456\u043d\u0456\u044e";
  this.aey = "\u0410\u0434\u0440\u0435\u0441\u0430 \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.aez = "\u044f\u043a \u0443 \u0457\u0457 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u0456-\u0437\u0430\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u0456 \u043f\u0456\u0441\u043b\u044f ?node=";
  this.adG = "\u0417\u043c\u0456\u043d\u0438\u0442\u0438";
  this.aeB = "\u041b\u0456\u043d\u0456\u044e \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.aeA = "\u041b\u0456\u043d\u0456\u044e \u043d\u0435 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.aeD = "\u0422\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0440\u0430\u0445\u0443\u0454 \u0432 \u0456\u043d\u0448\u0456\u0439 \u043e\u0434\u0438\u043d\u0438\u0446\u0456: \u043b\u0456\u043d\u0456\u0457 \u043c\u0456\u0436 \u0440\u0456\u0437\u043d\u0438\u043c\u0438 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438 \u0449\u0435 \u043d\u0435 \u0437\u0440\u043e\u0431\u043b\u0435\u043d\u043e.";
  this.af3 = "\u0417\u0430 \u0446\u0456\u0454\u044e \u0430\u0434\u0440\u0435\u0441\u043e\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043d\u0435 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0454.";
  this.aeC = "\u0426\u0435 \u0441\u0430\u043c\u0430 \u043d\u0430\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430.";
  this.agL = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0432\u0441\u0442\u0443\u043f\u0438\u0442\u0438";
  this.adw = "\u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0456 (\u043d\u0430\u0439\u043f\u0440\u043e\u0441\u0442\u0456\u0448\u0435)";
  this.afN = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u044f\u043a\u0456 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u043e\u0432\u0430\u043d\u043e)";
  this.afM = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u0432 \u0443\u0441\u0456\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0456 \u043b\u0456\u043d\u0456\u0457";
  this.afG = "\u0412\u0430\u0448 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0437 \u043d\u0443\u043b\u044f \u0439 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u043d\u0435 \u043e\u043f\u0443\u0441\u043a\u0430\u0454\u0442\u044c\u0441\u044f. \u041f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0449\u043e\u0441\u044c \u0430\u0431\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u0439\u0442\u0435 \u0440\u043e\u0431\u043e\u0442\u0443 \u0434\u043b\u044f \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430 \u2014 \u0456 \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0439\u0442\u0435 \u0437\u0430\u0440\u043e\u0431\u043b\u0435\u043d\u0435.";
  this.aeX = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0457 \u043e\u0441\u043e\u0431\u0438 \u0432 \u0446\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043d\u0435 \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u0438\u0442\u0438, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0442\u0438.";
  this.ag7 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.ag6 = "\u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0438\u0439 \u0442\u0435\u043a\u0441\u0442: \u0439\u043e\u0433\u043e \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043a\u043e\u0436\u0435\u043d \u043d\u043e\u0432\u0430\u0447\u043e\u043a. \u041f\u0435\u0440\u0448 \u043d\u0456\u0436 \u043d\u0430 \u043d\u044c\u043e\u0433\u043e \u043f\u043e\u043a\u043b\u0430\u0434\u0430\u0442\u0438\u0441\u044f, \u043f\u043e\u043a\u0430\u0436\u0456\u0442\u044c \u0439\u043e\u0433\u043e \u044e\u0440\u0438\u0441\u0442\u043e\u0432\u0456.";
  this.agk = "1. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u0432\u0435\u0434\u0435 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u043e\u0433\u043e, \u0449\u043e \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442\u044c \u043e\u0434\u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0439 \u0431\u0435\u0440\u0443\u0442\u044c \u043e\u0434\u043d\u0435 \u0432 \u043e\u0434\u043d\u043e\u0433\u043e. \u041e\u0434\u0438\u043d\u0438\u0446\u044f \u2014 \u043c\u0456\u0440\u0430 \u0432 \u0446\u044c\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443; \u0443 \u0446\u0456\u043d\u0430\u0445 \u0432\u043e\u043d\u0430 \u0440\u0430\u0445\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u043e\u0434\u043d\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u044f \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0457 \u0432\u0430\u043b\u044e\u0442\u0438.\n2. \u041e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043d\u0435 \u0433\u0440\u043e\u0448\u0456. \u041d\u0456\u0445\u0442\u043e \u0439 \u043d\u0456\u043a\u043e\u043b\u0438 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0454, \u043d\u0435 \u043a\u0443\u043f\u0443\u0454 \u0456 \u043d\u0435 \u043e\u0431\u043c\u0456\u043d\u044e\u0454 \u0457\u0445 \u043d\u0430 \u0433\u0440\u043e\u0448\u0456.\n3. \u0411\u0430\u043b\u0430\u043d\u0441 \u0432\u0438\u0449\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u043a\u0430\u0437\u0443\u0454, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0434\u0430\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0443\u0437\u044f\u0432; \u0431\u0430\u043b\u0430\u043d\u0441 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u2014 \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0432\u0456\u043d \u0443\u0437\u044f\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0434\u0430\u0432, \u0456 \u043c\u0430\u0454 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u0441\u0432\u043e\u0457\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u0430\u043c\u0438 \u0439 \u043f\u043e\u0441\u043b\u0443\u0433\u0430\u043c\u0438.\n4. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0443 \u043b\u0456\u043d\u0456\u044e \u0456 \u0441\u0442\u0435\u043b\u044e; \u0457\u0445 \u0437\u0430\u0434\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0439 \u043c\u043e\u0436\u0435 \u0437\u043c\u0456\u043d\u044e\u0432\u0430\u0442\u0438.\n5. \u0423\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u0456 \u0432\u043e\u043d\u0430 \u0437\u043d\u0430\u0454 \u0457\u0445 \u0437\u0430 \u0441\u043f\u0440\u0430\u0432\u0436\u043d\u0456\u043c\u0438 \u0456\u043c\u0435\u043d\u0430\u043c\u0438.\n6. \u041f\u0440\u043e\u0434\u0430\u0436 \u0437\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0441\u0430\u043c \u0432\u0438\u0441\u0442\u0430\u0432\u043b\u044f\u0454 \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439 \u0441\u0430\u043c \u0441\u043f\u043b\u0430\u0447\u0443\u0454 \u043f\u043e\u0434\u0430\u0442\u043a\u0438, \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u044f\u043a \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0443.\n7. \u0423\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u043e\u0436\u0435 \u0432\u0438\u0439\u0442\u0438 \u0431\u0443\u0434\u044c-\u043a\u043e\u043b\u0438, \u0437\u0432\u0456\u0432\u0448\u0438 \u0431\u0430\u043b\u0430\u043d\u0441 \u0434\u043e \u043d\u0443\u043b\u044f. \u0422\u043e\u0439, \u0445\u0442\u043e \u0432\u0438\u0445\u043e\u0434\u0438\u0442\u044c \u0456\u0437 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f, \u043f\u043e\u0433\u0430\u0448\u0430\u0454 \u0440\u0456\u0437\u043d\u0438\u0446\u044e \u0433\u0440\u043e\u0448\u0438\u043c\u0430 \u043f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 30 \u0434\u043d\u0456\u0432.\n8. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0437\u0430\u043a\u0440\u0438\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430, \u044f\u043a\u0438\u0439 \u043f\u043e\u0440\u0443\u0448\u0443\u0454 \u0446\u0456 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.";
  this.acU = "\u041f\u0440\u0438\u0439\u043c\u0430\u044e";
  this.ag4 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430";
  this.ag8 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e";
